code:
control "{cwe_id}" do
  title "{description}

 location: {aggregated_location}"
  desc "rational"
. desc 'check' {applicable_platforms}
  desc 'fix', "{potential_mitigations}"

  impact {impact}
  tag 'severity': {severity}
  tag 'nist': {sorted(list(set(nist_controls)))}
 tag 'grc': {sorted(list(set(grc_controls)))}
  tag 'cwe': {'CWE-' + cwes[0] if cwes else ''}
  tag 'owasp': {owasp_ids}
  tag 'cci': []
. tag 'category': {vuln.get('category', '')}
  tag 'org_ref': {sorted(list(set(org_refs)))}
  tag 'nist_references': {sorted(list(set(nist_references)))}
  tag 'related_controls': {sorted(list(set(related_controls)))}
